deepml motion 0.3
module corpus.deepml_motion.example_04751
policy deterministic
policy no_network
skeleton Rig04751 { joint Root parent none joint Hip parent Root joint FootL parent Hip joint FootR parent Hip }
procedural animation Procedural04751 seed 4751 {
  trajectory = predict_trajectory(velocity, horizon=1.0s)
