  constrain contact FootL to ground when phase < 0.5
  constrain contact FootR to ground when phase >= 0.5
}
layered state_machine Layers04751 { base: Locomotion upper: Gesture additive: Breathing }
synchronize Procedural04751 with scene.Actor8 and timeline.Sequence6

